import assert from 'node:assert/strict';
import { test } from 'node:test';

// With --test-only, the unfocused regression is omitted.
test('unfocused regression', () => {
  throw new Error('the regression must fail when the full suite runs');
});

test('selected passing case', { only: true }, () => {
  assert.equal(1 + 1, 2);
});
